import { motion, useReducedMotion } from "framer-motion";

import { AiSeal } from "./AiSeal";

export type PlanetImageId = "earth" | "moon" | "mars" | "steam" | "science";

interface PaperPlanetImageProps {
  planet: PlanetImageId;
  className?: string;
  /** Slow idle float; off inside dense layouts. */
  floating?: boolean;
  /** Shared-layout id so the planet can fly between places (framer-motion layoutId). */
  layoutId?: string;
}

/**
 * Cardboard planet generated by GPT (docs/design/paper-cut/PROMPTS_PLANETAS_GPT.md), always
 * shown with its visible AI seal. Decorative: the surrounding button carries the accessible name.
 */
export function PaperPlanetImage({ planet, className = "h-32 w-32", floating = true, layoutId }: PaperPlanetImageProps) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.span layoutId={layoutId} className={`relative inline-block ${className}`}>
      <motion.img
        src={`/img/planets/ckepi-planet-${planet}.webp`}
        alt=""
        width={1024}
        height={1024}
        draggable={false}
        decoding="async"
        className="h-full w-full select-none object-contain drop-shadow-ckepi-logo"
        animate={floating && !reduceMotion ? { y: [0, -6, 0], rotate: [0, 1.5, 0] } : undefined}
        transition={{ duration: 6, repeat: Infinity, ease: "easeInOut" }}
      />
      <AiSeal className="absolute bottom-[6%] right-[4%]" />
    </motion.span>
  );
}
